INSERT INTO hotels (id,name,location,area,description,image_url,rating,reviews,badge) VALUES
('h1','The Leela Palace','Udaipur, Rajasthan','Udaipur','A lakeside palace where the romance of Rajasthan meets warm, thoughtful hospitality.','https://images.unsplash.com/photo-1566073771259-6a8506099945?auto=format&fit=crop&w=900&q=85',4.9,1284,'Guest favourite'),
('h2','Taj Mahal Palace','Colaba, Mumbai','Mumbai','An icon on the waterfront, known for gracious service and unforgettable city views.','https://images.unsplash.com/photo-1542314831-068cd1dbfeeb?auto=format&fit=crop&w=900&q=85',4.8,2051,'Iconic stay'),
('h3','The Oberoi','Gurugram, Delhi NCR','Delhi','A serene urban retreat with contemporary design, fine dining and impeccable service.','https://images.unsplash.com/photo-1571896349842-33c89424de2d?auto=format&fit=crop&w=900&q=85',4.9,876,'Top rated'),
('h4','Ahilya by the Sea','Nerul, Goa','Goa','A beautifully intimate coastal hideaway tucked between palms and the Arabian Sea.','https://images.unsplash.com/photo-1571896349842-33c89424de2d?auto=format&fit=crop&w=900&q=85',4.8,642,'Hidden gem'),
('h5','Wildflower Hall','Shimla, Himachal Pradesh','Shimla','A mountain sanctuary above the clouds, surrounded by cedar forest and Himalayan air.','https://images.unsplash.com/photo-1510798831971-661eb04b3739?auto=format&fit=crop&w=900&q=85',4.9,511,'Mountain escape'),
('h6','The Tamara Coorg','Yevakapadi, Coorg','Coorg','Slow down in a hillside hideaway framed by coffee estates and misty green valleys.','https://images.unsplash.com/photo-1445019980597-93fa8acb246c?auto=format&fit=crop&w=900&q=85',4.7,728,'Nature retreat');
